// Authored content for 3.1.9.1 Meiosis (OxfordAQA 9610 v5.1, page 18; statements 3.1.9.1.s1–s5 in data/spec.js).
// The specification asks for meiosis "only in sufficient detail to show how" haploid cells form, how independent
// segregation and crossing over produce variation, plus random fertilisation and the interpretation of drawings and
// photographs. Stage names (prophase I etc.) are NOT required: they appear only as supporting labels and no question
// depends on them. Drawings and counts come from the model in data/content/_meiosis-art.js.
window.BIO = window.BIO || {}; window.BIO.content = window.BIO.content || {};
(function () {
  const A = window.BIO.meiosisArt, M = window.BIO.meiosisModel;
  const R = "3.1.9.1";
  const S = (...n) => n.map((k) => `${R}.s${k}`);
  const P = (slot) => window.BIO.views.photo(slot);

  // ---- Chromosome-counting challenge: cells drawn from the model; answers derived from the same items ----
  const countCell = (id, org, pt, side, state, stem, o = {}) => {
    const m = M.build(org, state); const items = A.stageItems(m, pt, side);
    const chromosomes = items.reduce((n, it) => n + (it.biv ? 2 : 1), 0); const per = (items[0].biv ? items[0].L : items[0].c).cds.length;
    const ploidy = ["g1", "rep", "paired", "cross", "metI", "mitosis"].includes(pt) ? "diploid" : "haploid";
    const fig = A.cellFigure(m, pt, side, { k: o.k || (["metI", "metII", "mitosis"].includes(pt) ? 0.85 : 1.15), tags: false, aria: o.aria || "drawing of a cell for counting chromosomes" });
    return { id: `q-${R}-cc${id}`, ref: R, stmts: S(5, 1), type: "gap", marks: 3, stem: `${stem}<div class="figure"><div class="fig-view">${fig}</div></div>`, text: "Number of chromosomes in this cell: {{1}}. Number of chromatids in each chromosome: {{2}}. This cell is haploid or diploid: {{3}}.", answers: { 1: [String(chromosomes), WORDS[chromosomes]], 2: [String(per), per === 1 ? "one" : "two"], 3: [ploidy] }, explanation: o.explain || "" , _counts: { chromosomes, per, ploidy } };
  };
  const WORDS = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve"];
  const strip = (q) => { delete q._counts; return q; };
  const cc = [
    countCell(1, "three", "g1", 0, {}, "Cell 1. A cell from an animal, drawn before DNA replication. Count the chromosomes by their centromeres (dark dots).", { explain: "Six chromosomes, each a single DNA molecule (one chromatid). There are three matching pairs (three lengths, two of each), so the cell is diploid (2n = 6)." }),
    countCell(2, "two", "paired", 0, { cross: [false, false] }, "Cell 2. A cell in which homologous chromosomes have come together in pairs.", { explain: "Four centromeres, so four chromosomes, arranged as two homologous pairs; each chromosome has two chromatids because the DNA has replicated. Pairs present: diploid (2n = 4)." }),
    countCell(3, "three", "metI", 0, { cross: [true, false, false], orient: [true, false, true] }, "Cell 3. A dividing cell from the same species as cell 1 (2n = 6).", { explain: "Six chromosomes (six centromeres) in three homologous pairs on the equator, each chromosome with two chromatids: the first division of meiosis, still diploid. A chiasma is visible in the longest pair." }),
    countCell(4, "three", "metII", 1, { cross: [true, false, false], orient: [true, false, true] }, "Cell 4. Another dividing cell from the same organism (2n = 6).", { explain: "Three chromosomes, one of each kind, so no pairs: haploid (n = 3). Each chromosome still has two chromatids and they sit singly on the equator: the second division of meiosis. One chromosome has a two-colour chromatid, the result of crossing over." }),
    countCell(5, "four", "end", 2, { orient: [true, false, false, true] }, "Cell 5. A cell produced at the end of meiosis in an organism with 2n = 8.", { explain: "Four chromosomes, each a single chromatid, one of each kind: a haploid cell (n = 4) produced by the second division. Note its mixture of maternal (red) and paternal (blue) chromosomes." }),
    countCell(6, "four", "rep", 0, {}, "Cell 6. A cell from the same organism (2n = 8) after DNA replication, before the chromosomes pair.", { explain: "Eight chromosomes (eight centromeres), each made of two sister chromatids, so 16 chromatids in all; four matching pairs: diploid." }),
    countCell(7, "two", "afterI", 0, { cross: [true, false], orient: [false, true] }, "Cell 7. One of the two cells formed by the first division in an organism with 2n = 4.", { explain: "Two chromosomes, each with two chromatids: the chromosome number halved in the first division (haploid, n = 2) but the sister chromatids have not yet separated. The DNA content is 2x, the same as the parent cell before replication." }),
    countCell(8, "two", "mitosis", 0, {}, "Cell 8. A dividing body cell from the organism with 2n = 4.", { explain: "Four chromosomes (four centromeres), each with two chromatids, sitting singly on the equator. Matching chromosomes are present but are not paired: this is mitosis (3.2.10), and the cell is diploid." }),
  ];
  const whichDiv = (id, org, pt, side, state, stem, answer, explanation) => { const m = M.build(org, state); const fig = A.cellFigure(m, pt, side, { k: 0.8, tags: false, aria: "drawing of a dividing cell" }); return { id: `q-${R}-wd${id}`, ref: R, stmts: S(5), type: "mcq", marks: 1, stem: `${stem}<div class="figure"><div class="fig-view">${fig}</div></div>`, options: ["The first division of meiosis", "The second division of meiosis", "Mitosis", "The cell is not dividing"], answer, explanation }; };
  const wd = [
    whichDiv(1, "four", "metII", 0, { orient: [true, true, false, false] }, "This cell comes from an animal with 2n = 8. Which division is it undergoing?", 1, "Four single chromosomes (n = 4, no matching pairs) on the equator, each with two chromatids: the second division of meiosis."),
    whichDiv(2, "four", "metI", 0, { orient: [true, false, true, false] }, "This cell comes from the same animal (2n = 8). Which division is it undergoing?", 0, "Eight chromosomes arranged as four homologous pairs on the equator: only the first division of meiosis pairs homologous chromosomes."),
    whichDiv(3, "three", "mitosis", 0, {}, "This cell comes from an animal with 2n = 6. Which division is it undergoing?", 2, "Six chromosomes, each with two chromatids, lined up singly (not paired) on the equator: the diploid number unpaired is mitosis."),
  ];

  window.BIO.content[R] = {
    status: "reviewed",
    banner: "meiosis-lm", bannerText: "One diploid cell, two divisions, four haploid cells that are genetically different from each other. Meiosis is where genetic variation is shuffled before every generation.",
    keywords: ["meiosis", "haploid", "diploid", "homologous chromosomes", "maternal", "paternal", "chromatid", "sister chromatids", "centromere", "independent segregation", "independent assortment", "crossing over", "chiasma", "chiasmata", "recombinant", "random fertilisation", "gamete", "zygote", "genetic variation", "2^n", "first division", "second division", "bivalent", "allele", "locus"],
    notes: () => `
<div class="notice"><strong>What the specification requires (3.1.9.1).</strong> Meiosis produces daughter cells that are genetically different from each other. It is studied <em>only in enough detail to show how</em>: (1) nuclear divisions produce <strong>haploid</strong> daughter cells from a single <strong>diploid</strong> parent cell; (2) <strong>independent segregation</strong> of homologous chromosomes gives genetically different daughter cells through different combinations of maternal and paternal chromosomes; (3) <strong>crossing over</strong> between homologous chromosomes gives further genetic variation. (4) <strong>Random fertilisation</strong> of haploid gametes further increases genetic variation within a species. (5) You should be able to describe and explain the behaviour of chromosomes in drawings or photographs of meiosis. <strong>The names of the stages (prophase I, metaphase II and so on) are not required.</strong> They appear on this page only as small supporting labels; describe what the chromosomes are doing instead. <span class="badge teal">required</span> <span class="badge">supporting</span> <span class="badge amber">extension</span></div>

<h2 data-stmt="${R}.s1 ${R}.s2 ${R}.s5">1. Chromosomes, homologous pairs, haploid and diploid <span class="badge teal">required</span></h2>
<ul><li>The body cells of most animals and plants are <strong>diploid</strong>: they contain <strong>two sets</strong> of chromosomes, one set inherited from each parent. The chromosomes therefore come in <strong>homologous pairs</strong>, and the number of chromosomes is written <strong>2n</strong> (humans 2n = 46, 23 pairs).</li>
<li><strong>Homologous chromosomes</strong> are a pair of chromosomes, one <strong>maternal</strong> (from the mother) and one <strong>paternal</strong> (from the father), that carry the <strong>same genes at the same loci</strong>. They are the same length and have their centromeres in the same position. They need not carry the same <em>alleles</em>: the maternal chromosome might carry allele A where the paternal one carries allele a. <span class="badge">supporting</span> An allele is a different form of the same gene, found at the same locus (defined formally in 3.3.6).</li>
<li>A <strong>haploid</strong> cell contains <strong>one set</strong> of chromosomes, one from each homologous pair, written <strong>n</strong> (human gametes n = 23). A haploid cell has no homologous pairs.</li></ul>
<p><span class="badge">supporting</span> <strong>Chromosomes and chromatids.</strong> Before a cell divides, its DNA replicates (3.1.7.3). Each chromosome then consists of two identical <strong>sister chromatids</strong> (two DNA molecules) held together at the <strong>centromere</strong>. It is still <em>one</em> chromosome. When you count chromosomes in a drawing or photograph, <strong>count centromeres</strong>, not arms or chromatids.</p>
<div class="figure"><div class="fig-view">${A.homologues()}</div></div>

<h2 data-stmt="${R}.s1">2. Meiosis: two nuclear divisions, four haploid cells <span class="badge teal">required</span></h2>
<p>Meiosis is a type of nuclear division that halves the chromosome number. One <strong>diploid</strong> parent cell undergoes <strong>two nuclear divisions</strong>, one after the other, to produce <strong>four haploid</strong> daughter cells that are <strong>genetically different</strong> from each other and from the parent cell. In animals these cells develop into gametes.</p>
<ol><li><span class="badge">supporting</span> <strong>Before meiosis, the DNA replicates</strong>, so each chromosome is two sister chromatids.</li>
<li><strong>First division: homologous chromosomes separate.</strong> The homologous chromosomes come together in pairs (and crossing over happens, section 4). The pairs line up across the middle (equator) of the cell, and the two chromosomes of each pair are pulled to opposite ends (poles). Each of the two new cells receives <strong>one chromosome from every pair</strong>, so it is <strong>haploid</strong>. Each chromosome still has two chromatids.</li>
<li><strong>Second division: sister chromatids separate.</strong> In each haploid cell the chromosomes line up singly on the equator, and the two chromatids of each chromosome are pulled to opposite poles. Four haploid cells result, each chromosome now a single chromatid. The chromosome number per cell stays at n: what halves this time is the DNA content.</li></ol>
<div class="figure"><div class="fig-view">${A.overview()}</div></div>
<table class="tbl"><thead><tr><th>Point in meiosis (model cell, 2n = 4)</th><th>Cells</th><th>Chromosomes per cell</th><th>Chromatids per chromosome</th><th>DNA per cell <span class="badge">supporting</span></th><th>Haploid or diploid</th></tr></thead><tbody>
<tr><td>Parent cell before DNA replication</td><td>1</td><td>4</td><td>1</td><td>2x</td><td>diploid</td></tr>
<tr><td>After DNA replication; pairs form; crossing over</td><td>1</td><td>4</td><td>2</td><td>4x</td><td>diploid</td></tr>
<tr><td>After the first division</td><td>2</td><td>2</td><td>2</td><td>2x</td><td>haploid</td></tr>
<tr><td>After the second division</td><td>4</td><td>2</td><td>1</td><td>x</td><td>haploid</td></tr></tbody></table>
<p class="small muted"><span class="badge">supporting</span> x is the DNA content of one gamete. For reference only, textbooks name the steps prophase I (pairing and crossing over), metaphase I (pairs on the equator), anaphase I (homologous chromosomes separate), telophase I, then prophase II, metaphase II, anaphase II (sister chromatids separate) and telophase II. You do not need these names for 3.1.9.</p>
<p><span class="badge">supporting</span> <strong>Why halve the number?</strong> At fertilisation two gametes fuse. If each were diploid, the chromosome number would double every generation. Haploid gametes (n) fuse to restore the diploid number (2n) in the zygote, so the number stays constant from generation to generation.</p>

<h2 data-stmt="${R}.s2">3. Independent segregation of homologous chromosomes <span class="badge teal">required</span></h2>
<p>In the first division the homologous pairs line up on the equator. <strong>Which chromosome of a pair (maternal or paternal) faces which pole is a matter of chance, and each pair lines up independently of every other pair.</strong> When the homologous chromosomes separate, each daughter cell receives one chromosome of every pair, but a <strong>random combination of maternal and paternal chromosomes</strong>. Different meioses (and the two cells of one meiosis) therefore receive different combinations, so the daughter cells are genetically different.</p>
<p>Independent segregation explains differences in <em>which whole chromosomes</em> the cells receive. On its own it does not explain all the differences between the products of meiosis: without crossing over, the four cells from one meiosis form two identical pairs. Crossing over (section 4) is needed for all four to differ.</p>
<div class="figure"><div class="fig-view">${A.segregation()}</div></div>
<ul><li>Independent segregation shuffles <strong>whole chromosomes</strong>. It does not change the alleles carried on any one chromosome.</li>
<li>It produces variation because homologous chromosomes may carry <strong>different alleles</strong> of their genes; if a pair carried identical alleles at every locus, it would make no genetic difference which one a cell received.</li>
<li><span class="badge">supporting</span> <strong>Counting combinations.</strong> Each pair can go either way, so with <strong>n</strong> homologous pairs the number of possible combinations of maternal and paternal chromosomes in the gametes is <strong>2ⁿ</strong> (crossing over ignored). 2 pairs: 2² = 4; 3 pairs: 2³ = 8; humans, 23 pairs: 2²³ = <strong>8 388 608</strong>. Remember n is the number of <em>pairs</em>: if you are given 2n, halve it first. The chance that a gamete receives only maternal chromosomes is (½)ⁿ.</li></ul>
<div class="notice"><strong>Worked example.</strong> A plant has 2n = 14. It has 14 ÷ 2 = 7 homologous pairs, so independent segregation alone gives 2⁷ = <strong>128</strong> different combinations of chromosomes in its gametes.</div>

<h2 data-stmt="${R}.s3">4. Crossing over between homologous chromosomes <span class="badge teal">required</span></h2>
<p>While the homologous chromosomes are paired in the first division, a chromatid of the maternal chromosome and a chromatid of the paternal chromosome (<strong>non-sister chromatids</strong>) can wrap round each other. The point where they cross is a <strong>chiasma</strong> (plural <strong>chiasmata</strong>). The chromatids break and rejoin at the chiasma, so <strong>equivalent sections</strong> of DNA (the same genes, but possibly different alleles) are <strong>exchanged</strong> between them.</p>
<div class="figure"><div class="fig-view">${A.crossing()}</div></div>
<ul><li>The result is chromatids carrying <strong>new combinations of alleles</strong> that were not present on either parental chromosome: above, a maternal chromosome that carried A and B and a paternal one that carried a and b give chromatids carrying <strong>Ab</strong> and <strong>aB</strong>. These are called <strong>recombinant</strong> chromatids.</li>
<li>Crossing over is between <strong>non-sister</strong> chromatids of a <strong>homologous pair</strong>. Sister chromatids are identical copies, so an exchange between them would change nothing; non-homologous chromosomes carry different genes and do not pair.</li>
<li>Because of crossing over, the two sister chromatids of a chromosome are <strong>no longer identical</strong>. So when they separate in the second division, the two cells formed are also genetically different: <strong>all four cells</strong> from one meiosis can differ.</li>
<li>Crossing over combines with independent segregation to make the number of possible combinations enormously larger than 2ⁿ. <span class="badge">supporting</span> The positions of chiasmata vary from cell to cell, and a pair can form more than one.</li></ul>
${P("chiasmata-lm")}

<h2 data-stmt="${R}.s4">5. Random fertilisation <span class="badge teal">required</span></h2>
<p>At <strong>fertilisation</strong> a haploid male gamete fuses with a haploid female gamete to form a diploid zygote. Because meiosis makes every gamete genetically different, and <strong>any male gamete can fuse with any female gamete</strong> (which ones meet is a matter of chance), each zygote receives a new, unpredictable combination of alleles from two parents. Random fertilisation therefore <strong>further increases genetic variation within a species</strong>. It is <em>not</em> part of meiosis: it happens after it.</p>
<div class="figure"><div class="fig-view">${A.fertilisation()}</div></div>
<p><span class="badge">supporting</span> If each parent can make 2ⁿ kinds of gamete (crossing over ignored), the number of possible chromosome combinations in a zygote is 2ⁿ × 2ⁿ = <strong>(2ⁿ)²</strong>. For humans: (2²³)² = 70 368 744 177 664, about <strong>7.0 × 10¹³</strong>, from one pair of parents, before crossing over is even counted. This is why siblings (other than identical twins) are genetically different.</p>

<h2 data-stmt="${R}.s2 ${R}.s3 ${R}.s4">6. Three sources of variation: keep them apart <span class="badge teal">required</span></h2>
<table class="tbl"><thead><tr><th></th><th>Independent segregation</th><th>Crossing over</th><th>Random fertilisation</th></tr></thead><tbody>
<tr><th>When</th><td>First division of meiosis, as homologous pairs line up and separate</td><td>First division of meiosis, while homologous chromosomes are paired</td><td>After meiosis, when gametes fuse</td></tr>
<tr><th>What is shuffled</th><td>Whole chromosomes: which homologue (maternal or paternal) of each pair goes into which cell</td><td>Sections of chromatids: alleles exchanged between non-sister chromatids</td><td>Whole gametes: which gamete from one parent fuses with which from the other</td></tr>
<tr><th>Produces</th><td>Different combinations of maternal and paternal chromosomes in the daughter cells</td><td>New combinations of alleles on chromosomes (recombinant chromatids)</td><td>New combinations of alleles from two parents in each zygote</td></tr>
<tr><th>Number of combinations</th><td>2ⁿ</td><td>Very large; depends on where chiasmata form</td><td>(2ⁿ)² (ignoring crossing over)</td></tr></tbody></table>
<p class="small">None of the three creates new alleles: new alleles arise by <strong>mutation</strong> (3.2.11). Meiosis and fertilisation produce new <em>combinations</em> of existing alleles.</p>

<h2 data-stmt="${R}.s5 ${R}.s1">7. Interpreting drawings and photographs of meiosis <span class="badge teal">required</span></h2>
<p>You may be shown a drawing or a light micrograph (often a squash of an anther or a testis, where many cells are dividing) and asked to describe or explain what the chromosomes are doing. Work through these questions:</p>
<ol><li><strong>How many chromosomes?</strong> Count the centromeres. Compare with the diploid number if you are given it.</li>
<li><strong>Are the chromosomes in matching pairs?</strong> If every chromosome has a partner of the same length and centromere position, the cell is diploid; if each kind appears only once, it is haploid.</li>
<li><strong>Is each chromosome two chromatids or one?</strong> Two chromatids means the DNA has replicated and the chromatids have not yet separated.</li>
<li><strong>Are homologous chromosomes lying side by side?</strong> Pairs of homologous chromosomes, often with chiasmata visible as crosses between chromatids, are seen only in the first division of meiosis.</li>
<li><strong>What is moving apart?</strong> Whole chromosomes (each still two chromatids) moving to opposite poles: homologous chromosomes separating in the first division. Single chromatids moving apart: the second division (or mitosis).</li>
<li><strong>How many cells, grouped how?</strong> Two cells side by side suggest the end of the first division; four cells together (a group of four) are the products of the second division.</li></ol>
<div class="figure"><div class="fig-view">${A.whichDivision()}</div></div>
<div class="notice amber"><strong>Common traps.</strong> A chromosome with two chromatids is still one chromosome. A cell after the first division is <strong>haploid</strong> even though each chromosome still has two chromatids. In the second division the chromosome number does not halve again; the chromatids separate. If a drawing shows the diploid number lined up singly with no pairing, it is mitosis, not meiosis.</div>
${P("meiosis-lm")}

<h2 data-stmt="${R}.s1 ${R}.s5">8. DNA content through meiosis <span class="badge">supporting</span></h2>
<p>Taking x as the DNA content of one gamete: a diploid cell before replication contains 2x; replication doubles this to 4x; the first division halves it to 2x per cell; the second halves it again to x. So the DNA content halves twice, but the <strong>chromosome number</strong> halves only once (in the first division). Questions often give a graph like this and ask which division a fall represents.</p>
<div class="figure"><div class="fig-view">${A.dnaGraph()}</div></div>

<h2 data-stmt="${R}.s1">9. Meiosis compared with mitosis <span class="badge">supporting</span></h2>
<p>Mitosis is taught in 3.2.10; this comparison is here only to help you tell the two apart.</p>
<table class="tbl"><thead><tr><th></th><th>Mitosis</th><th>Meiosis</th></tr></thead><tbody>
<tr><th>Nuclear divisions</th><td>One</td><td>Two</td></tr><tr><th>Daughter cells</th><td>Two</td><td>Four</td></tr>
<tr><th>Chromosome number</th><td>Same as the parent cell (diploid stays diploid)</td><td>Halved (diploid parent, haploid daughters)</td></tr>
<tr><th>Homologous chromosomes</th><td>Do not pair</td><td>Pair, then separate in the first division</td></tr>
<tr><th>Crossing over, independent segregation</th><td>No</td><td>Yes</td></tr>
<tr><th>Daughter cells genetically</th><td>Identical to each other and to the parent</td><td>Different from each other and from the parent</td></tr>
<tr><th>Role</th><td>Growth, repair, asexual reproduction</td><td>Production of gametes for sexual reproduction</td></tr></tbody></table>`,
    diagrams: [
      { id: "d-3.1.9.1-1", title: "Meiosis from one diploid cell to four haploid cells", status: "reviewed", caption: "A model cell with two homologous pairs (2n = 4; maternal red, paternal blue). The DNA replicates; homologous chromosomes pair and cross over; the first division separates homologous chromosomes (chromosome number halves); the second separates sister chromatids. Counts per cell are under each panel; x is the DNA content of one gamete. With crossing over in the long pair, all four cells differ (AB D, Ab D, aB d, ab d).", alt: "Five panels from left to right: a diploid cell with four single-chromatid chromosomes; the same cell with each chromosome as two chromatids; two homologous pairs side by side, the long pair crossing over; two haploid cells each with two replicated chromosomes; four haploid cells each with two single-chromatid chromosomes, labelled AB D, Ab D, aB d and ab d. Beneath: 4, 4, 4, 2, 2 chromosomes per cell; 1, 2, 2, 2, 1 chromatids per chromosome; DNA 2x, 4x, 4x, 2x, x; diploid, diploid, diploid, haploid, haploid.", svg: A.overview() },
      { id: "d-3.1.9.1-2", title: "Chromosomes, chromatids and homologous pairs", status: "reviewed", caption: "A chromosome is counted by its centromere: after replication it is still one chromosome, made of two sister chromatids. Homologous chromosomes are the same length with the same centromere position and the same loci, one maternal and one paternal; their alleles may differ (A and a, B and b).", alt: "An unreplicated chromosome; a replicated chromosome of two chromatids joined at a centromere; a maternal and a paternal chromosome of the same length side by side with alleles A, B and a, b at matching positions; and a shorter chromosome that is not homologous with them.", svg: A.homologues() },
      { id: "d-3.1.9.1-3", title: "Crossing over at a chiasma", status: "reviewed", caption: "Non-sister chromatids of a homologous pair cross at a chiasma, break and rejoin, exchanging equivalent sections. Two of the four chromatids become recombinant (Ab and aB). Simplified textbook representation.", alt: "Three panels: a homologous pair of four chromatids with alleles A B on the maternal chromatids and a b on the paternal ones; the two inner chromatids crossing at a chiasma; the separated chromosomes with chromatids AB, Ab (maternal top, paternal bottom), aB and ab.", svg: A.crossing() },
      { id: "d-3.1.9.1-4", title: "Independent segregation of two homologous pairs", status: "reviewed", caption: "The two pairs line up independently, giving two equally likely arrangements and 2² = 4 combinations of maternal and paternal chromosomes in the gametes. Crossing over is omitted so that this mechanism can be seen alone.", alt: "Two rows. In the first, both maternal chromosomes face the left pole, giving gametes with both maternal or both paternal chromosomes. In the second, the maternal long and paternal short chromosomes face the same pole, giving gametes with one maternal and one paternal chromosome.", svg: A.segregation() },
      { id: "d-3.1.9.1-5", title: "Random fertilisation", status: "reviewed", caption: "Each parent with two homologous pairs makes four kinds of gamete; any sperm can fertilise any egg, giving 4 × 4 = 16 chromosome combinations in the zygote, (2ⁿ)² with n = 2. In this diagram only, blue means from the father and red from the mother; the shade (dark or light) shows which grandparent each chromosome came from.", alt: "A four-by-four grid: four kinds of sperm across the top, four kinds of egg down the side, and sixteen different zygotes in the grid, each with a long and a short chromosome from each parent.", svg: A.fertilisation() },
      { id: "d-3.1.9.1-6", title: "Which division is this?", status: "reviewed", caption: "First division of meiosis: homologous pairs on the equator. Second division: the haploid number of single chromosomes on the equator. Mitosis (for comparison): the diploid number of single chromosomes, unpaired.", alt: "Three dividing cells: one with two homologous pairs straddling the equator, one with two single chromosomes on the equator, and one with four single chromosomes on the equator.", svg: A.whichDivision() },
      { id: "d-3.1.9.1-7", title: "DNA content per cell through meiosis", status: "reviewed", caption: "2x before replication, 4x after, 2x after the first division and x after the second. The DNA content halves twice; the chromosome number halves only in the first division.", alt: "Step graph of DNA content per cell against time: level at 2x, a rise to 4x during replication, a drop to 2x at the first division and to x at the second division.", svg: A.dnaGraph() },
    ],
    interactives: [
      { kind: "meioModel", title: "Meiosis Model", note: "Step through meiosis in a model cell. Switch crossing over on or off, choose how each homologous pair lines up in the first division, and see which four haploid cells you get. Counts per cell are shown at every step.",
        items: [{ label: "Questions on the model", questions: [
          { id: `q-${R}-mo1`, ref: R, stmts: S(1, 2), type: "mcq", marks: 1, stem: "Switch crossing over off and run the model to the end. The four cells produced from one meiosis are:", options: ["all genetically identical", "two pairs of genetically identical cells", "all four genetically different", "two haploid and two diploid cells"], answer: 1, explanation: "Without crossing over, sister chromatids are identical, so the two cells made from each product of the first division are identical: two pairs. The two pairs differ because, when the homologous chromosomes separated, each product of the first division received a different combination of maternal and paternal chromosomes (independent segregation). Crossing over is needed for all four cells to differ." },
          { id: `q-${R}-mo2`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "With crossing over off, try every arrangement of the pairs in the 2n = 4 cell. How many different combinations of maternal and paternal chromosomes can the gametes have?", options: ["2", "4", "8", "16"], answer: 1, explanation: "Two pairs, each able to face either way: 2² = 4 combinations (both maternal, both paternal and two mixed)." },
          { id: `q-${R}-mo3`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Switch crossing over on in the long pair. In how many of the four cells is the long chromosome recombinant (a new combination of the A and B alleles)?", options: ["0", "1", "2", "4"], answer: 2, explanation: "Only the two non-sister chromatids that crossed over carry new combinations (Ab and aB); the other two chromatids are parental (AB and ab)." },
        ] }] },
      { kind: "meioCount", title: "Chromosome-Counting Challenge", note: "Cells drawn at different points. For each one give the number of chromosomes, the number of chromatids in each chromosome and whether the cell is haploid or diploid; then decide which division three dividing cells are in. Every answer is marked and recorded.",
        items: [...cc.map((q, i) => ({ label: `Cell ${i + 1}`, questions: [strip(q)] })), ...wd.map((q, i) => ({ label: `Division ${i + 1}`, questions: [q] }))] },
      { kind: "meioCombos", title: "Combinations Calculator", note: "Choose an organism or a number of homologous pairs and see how many combinations independent segregation (2ⁿ) and random fertilisation ((2ⁿ)²) can produce, before crossing over adds more.",
        items: [{ label: "Calculations", questions: [
          { id: `q-${R}-cb1`, ref: R, stmts: S(2), type: "gap", marks: 2, stem: "The onion (<em>Allium cepa</em>) has 2n = 16.", text: "Number of homologous pairs: {{1}}. Number of combinations of maternal and paternal chromosomes possible in its gametes by independent segregation: {{2}}.", answers: { 1: ["8"], 2: ["256"] }, explanation: "n = 16 ÷ 2 = 8 pairs; 2⁸ = 256." },
          { id: `q-${R}-cb2`, ref: R, stmts: S(2, 4), type: "gap", marks: 2, stem: "A mosquito, <em>Aedes aegypti</em>, has 2n = 6. Ignore crossing over.", text: "Combinations possible in one mosquito's gametes: {{1}}. Combinations possible in the zygotes produced by one pair of parents: {{2}}.", answers: { 1: ["8"], 2: ["64"] }, explanation: "n = 3: 2³ = 8 kinds of gamete from each parent; 8 × 8 = 64 combinations in the zygotes." },
          { id: `q-${R}-cb3`, ref: R, stmts: S(2), type: "gap", marks: 1, stem: "An organism can produce 512 combinations of chromosomes in its gametes by independent segregation alone.", text: "Its diploid number (2n) is {{1}}.", answers: { 1: ["18"] }, explanation: "2ⁿ = 512 so n = 9 pairs, and 2n = 18." },
        ] }] },
      { kind: "meioWhich", title: "Which Mechanism?", note: "Each scenario describes something that happens in a cell or an organism. Decide whether it is independent segregation, crossing over, random fertilisation or none of these.",
        items: [{ label: "Scenarios", questions: [
          ["wm1", S(3), "Two chromatids, one from the maternal and one from the paternal chromosome of a pair, exchange a section carrying the gene for flower colour.", 1, "Exchange between non-sister chromatids of a homologous pair is crossing over."],
          ["wm2", S(2), "In one cell the maternal chromosome 3 and the paternal chromosome 7 move to the same pole; in another cell from the same animal, the paternal 3 and the paternal 7 do.", 0, "Which homologue of each pair goes to which pole is independent of the other pairs: independent segregation."],
          ["wm3", S(4), "Of the millions of genetically different pollen grains landing on a stigma, one particular pollen grain's nucleus fuses with the egg cell.", 2, "Which male gamete fuses with which female gamete is a matter of chance: random fertilisation."],
          ["wm4", S(1), "A skin cell divides to give two cells with the same chromosomes as itself.", 3, "This is mitosis: the daughter cells are genetically identical, so no new variation arises."],
          ["wm5", S(3, 5), "A photograph shows a homologous pair whose chromatids form a cross-shaped connection between the two chromosomes.", 1, "A cross-shaped connection between non-sister chromatids is a chiasma, the site of crossing over."],
          ["wm6", S(2), "A gamete receives the paternal copy of every chromosome except chromosome 2, of which it receives the maternal copy.", 0, "A mixture of whole maternal and paternal chromosomes in one gamete results from independent segregation."],
          ["wm7", S(3), "A chromosome carries the alleles H and t, although the parent's maternal chromosome carried H and T and its paternal chromosome carried h and t.", 1, "A new combination of alleles on one chromosome (Ht) can only arise by exchange between homologous chromosomes: crossing over."],
          ["wm8", S(1), "Sister chromatids of a chromosome separate in a cell that has not undergone crossing over, producing two identical cells.", 3, "Separation of identical sister chromatids produces no new combination; with no crossing over the products are identical."],
          ["wm9", S(4), "A man produces millions of genetically different sperm. Which one of them fuses with a particular egg is a matter of chance.", 2, "The chance meeting of one particular male gamete with one particular female gamete is random fertilisation. (The sperm were already genetically different because of independent segregation and crossing over in the man's meiosis; this scenario describes the step after meiosis.)"],
        ].map(([k, st, stem, answer, explanation]) => ({ id: `q-${R}-${k}`, ref: R, stmts: st, type: "mcq", marks: 1, stem, options: ["Independent segregation", "Crossing over", "Random fertilisation", "None of these: no new genetic variation"], answer, explanation })).concat([
          { id: `q-${R}-wm10`, ref: R, stmts: S(2, 3, 4), type: "match", marks: 3, stem: "Match each mechanism to what it produces.", pairs: [{ left: "Independent segregation", right: "Different combinations of whole maternal and paternal chromosomes in daughter cells" }, { left: "Crossing over", right: "New combinations of alleles on a single chromosome" }, { left: "Random fertilisation", right: "A new combination of alleles from two parents in each zygote" }] },
        ]) }] },
    ],
    focus: [
      { slot: "meiosis-lm", title: "Meiosis in a lily anther", ref: R, explanation: () => `<p>Lily anthers are a classic material for seeing meiosis. Inside a young anther the pollen mother cells divide by meiosis more or less together, and lily chromosomes are large (a common garden lily has 2n = 24), so a squash of one anther, stained to show DNA, can show many cells at the same point. Cells in the first division show <strong>12 homologous pairs</strong>, each pair made of four chromatids and held together by chiasmata. Later, the cells are found in <strong>groups of four</strong>: each group is the product of one meiosis, and each of the four haploid cells (n = 12) goes on to form a pollen grain. Because of independent segregation and crossing over, the four cells of a group are genetically different, so even pollen grains from a single anther vary.</p>`,
        question: { id: `q-${R}-fx1`, ref: R, stmts: S(5, 1), type: "short", marks: 3, stem: "In a squash of a lily anther (2n = 24), a student sees one cell containing 12 structures, each made of four chromatids, and elsewhere groups of four cells each containing 12 chromosomes. Explain these two observations. (3 marks)", scheme: [{ point: "The 12 structures are homologous pairs (each two chromosomes of two chromatids = four chromatids) lying together in the first division", marks: 1 }, { point: "The cell is still diploid: 12 pairs = 24 chromosomes", marks: 1 }, { point: "Groups of four are the products of the second division: four haploid cells (n = 12) from one diploid cell, each chromosome a single chromatid", marks: 1 }], model: "Each structure is a pair of homologous chromosomes that have come together in the first division of meiosis; each chromosome has replicated into two chromatids, so a pair has four chromatids, and 12 pairs means the cell still has 24 chromosomes and is diploid. The groups of four cells are the result of the second division: one diploid cell has produced four haploid cells, each with one chromosome from each pair, 12 in all.", commonErrors: "Counting each four-chromatid structure as four chromosomes, or calling the cell haploid because it shows 12 structures." } },
      { slot: "chiasmata-lm", title: "Chiasmata you can see", ref: R, explanation: () => `<p>In cells from grasshopper and locust testes, which have large chromosomes, homologous pairs in the first division of meiosis can be seen under the light microscope held together at one or more points where their chromatids cross. These cross-shaped connections are <strong>chiasmata</strong>. A pair with one chiasma often looks like a cross; a pair with two chiasmata at opposite ends can open out into a ring. Each chiasma marks a place where non-sister chromatids have exchanged equivalent sections, so each one is visible evidence that crossing over has produced new combinations of alleles. Chiasmata also hold each pair together until the homologous chromosomes separate.</p>`,
        question: { id: `q-${R}-fx2`, ref: R, stmts: S(3, 5), type: "short", marks: 3, stem: "Explain how the chiasmata seen in photographs of dividing cells in a locust testis lead to genetic variation among the sperm produced. (3 marks)", scheme: [{ point: "A chiasma is where non-sister chromatids of a homologous pair cross / are joined", marks: 1 }, { point: "The chromatids break and rejoin there, exchanging equivalent sections (alleles)", marks: 1 }, { point: "Producing chromatids with new combinations of alleles, which end up in different sperm (sister chromatids now differ, so all four products of a meiosis can differ)", marks: 1 }], model: "Each chiasma is a point where a chromatid of the maternal chromosome and a chromatid of the paternal chromosome of a homologous pair cross. At that point the chromatids break and rejoin, so they exchange equivalent sections of DNA carrying the same genes but possibly different alleles. The recombinant chromatids carry new combinations of alleles, and because the two sister chromatids of each chromosome are now different, the four cells produced by the meiosis, and so the sperm, are genetically different.", commonErrors: "Saying chiasmata form between sister chromatids, or that crossing over creates new alleles." } },
    ],
    examFocus: `<ul><li>Count chromosomes by <strong>centromeres</strong>; a replicated chromosome (two chromatids) is one chromosome.</li><li>"Haploid" means one chromosome from each pair; a cell after the first division is haploid even though its chromosomes still have two chromatids.</li><li>First division: <strong>homologous chromosomes</strong> separate (number halves). Second division: <strong>sister chromatids</strong> separate (number stays n).</li><li>Independent segregation: say that <em>each pair lines up independently</em> and that this gives <em>different combinations of maternal and paternal chromosomes</em>. Crossing over: <em>non-sister chromatids of homologous chromosomes</em>, <em>chiasmata</em>, <em>exchange of equivalent sections</em>, <em>new combinations of alleles</em>. Random fertilisation: <em>any male gamete with any female gamete</em>.</li><li>Keep the three mechanisms separate; "crossing over of chromosomes" or "independent segregation of alleles" will not gain the marks.</li><li>2ⁿ uses the number of <strong>pairs</strong>: halve 2n first. With random fertilisation, (2ⁿ)².</li><li>Stage names are not required: describe what the chromosomes are doing.</li><li>Neither meiosis nor fertilisation creates new alleles: that is mutation.</li></ul>`,
    synoptic: [
      { ref: "3.1.7.2", text: "Genes occupy fixed loci on chromosomes; homologous chromosomes carry the same loci." },
      { ref: "3.1.7.3", text: "Semi-conservative replication before meiosis produces the two sister chromatids." },
      { ref: "3.2.10.2", text: "Mitosis: one division, two genetically identical cells; compare with meiosis." },
      { ref: "3.1.6", text: "Meiosis and random fertilisation generate genetic variation within a species." },
      { ref: "3.3.6.2", text: "Dihybrid crosses and autosomal linkage: recombinant offspring arise from crossing over." },
      { ref: "3.3.8.1", text: "Natural selection acts on the variation that meiosis and fertilisation produce." },
    ],
    quickCheck: [
      { id: `q-${R}-qc1`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "A diploid cell with 2n = 18 divides by meiosis. Each daughter cell contains:", options: ["9 chromosomes", "18 chromosomes", "36 chromosomes", "4.5 chromosomes"], answer: 0, explanation: "Meiosis halves the chromosome number: n = 9." },
      { id: `q-${R}-qc2`, ref: R, stmts: S(1, 2), type: "mcq", marks: 1, stem: "What separates in the first division of meiosis?", options: ["Sister chromatids", "Homologous chromosomes", "Non-homologous chromosomes", "The two strands of each DNA molecule"], answer: 1, explanation: "Homologous chromosomes separate in the first division; sister chromatids in the second." },
      { id: `q-${R}-qc3`, ref: R, stmts: S(2), type: "gap", marks: 1, stem: "Ignore crossing over.", text: "An organism with 4 homologous pairs of chromosomes can produce {{1}} different combinations of chromosomes in its gametes.", answers: { 1: ["16"] }, explanation: "2⁴ = 16." },
      { id: `q-${R}-qc4`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Crossing over takes place between:", options: ["sister chromatids of one chromosome", "non-sister chromatids of homologous chromosomes", "chromosomes of different pairs", "chromosomes of the two gametes at fertilisation"], answer: 1, explanation: "Non-sister chromatids of a homologous pair exchange equivalent sections." },
      { id: `q-${R}-qc5`, ref: R, stmts: S(4), type: "mcq", marks: 1, stem: "Random fertilisation increases genetic variation because:", options: ["it doubles the number of chromosomes in each gamete", "any male gamete can fuse with any female gamete", "it causes crossing over in the zygote", "it creates new alleles"], answer: 1, explanation: "Which genetically different gametes fuse is a matter of chance." },
    ],
    flashcards: [
      { id: `f-${R}-1`, front: "What does meiosis produce, and from what?", back: "Four haploid daughter cells, genetically different from each other, from one diploid parent cell, by two nuclear divisions." },
      { id: `f-${R}-2`, front: "Define diploid and haploid.", back: "Diploid (2n): two sets of chromosomes, in homologous pairs. Haploid (n): one set, one chromosome from each pair." },
      { id: `f-${R}-3`, front: "What are homologous chromosomes?", back: "A pair of chromosomes, one maternal and one paternal, with the same genes at the same loci (same length and centromere position); their alleles may differ." },
      { id: `f-${R}-4`, front: "Chromosome v chromatid.", back: "After DNA replication a chromosome is two identical sister chromatids joined at the centromere. It is still one chromosome; when the chromatids separate each becomes a chromosome." },
      { id: `f-${R}-5`, front: "How do you count chromosomes in a drawing or photograph?", back: "Count the centromeres. Two chromatids joined at one centromere is one chromosome." },
      { id: `f-${R}-6`, front: "What happens to the DNA before meiosis? (supporting)", back: "It replicates, so each chromosome consists of two sister chromatids and the DNA content doubles (2x to 4x)." },
      { id: `f-${R}-7`, front: "What separates in the first division of meiosis, and what is the result?", back: "Homologous chromosomes. Each of the two cells gets one chromosome from every pair, so the chromosome number halves: the cells are haploid (each chromosome still two chromatids)." },
      { id: `f-${R}-8`, front: "What separates in the second division of meiosis?", back: "Sister chromatids. The chromosome number per cell stays haploid; the DNA content halves (2x to x)." },
      { id: `f-${R}-9`, front: "In which division does the chromosome number halve?", back: "Only the first, when homologous chromosomes separate. The second division halves the DNA content but not the chromosome number." },
      { id: `f-${R}-10`, front: "What is independent segregation?", back: "In the first division, each homologous pair lines up on the equator independently of the others, so whether the maternal or paternal chromosome goes to a pole is random for each pair." },
      { id: `f-${R}-11`, front: "How does independent segregation produce genetic variation?", back: "Daughter cells receive different combinations of maternal and paternal chromosomes, which carry different alleles, so the cells are genetically different." },
      { id: `f-${R}-12`, front: "Number of chromosome combinations from independent segregation (supporting maths).", back: "2ⁿ, where n is the number of homologous pairs (halve 2n first). Crossing over ignored." },
      { id: `f-${R}-13`, front: "Humans have 23 pairs of chromosomes. How many combinations can independent segregation produce?", back: "2²³ = 8 388 608." },
      { id: `f-${R}-14`, front: "What is crossing over?", back: "Exchange of equivalent sections between non-sister chromatids of a homologous pair, at chiasmata, while the homologous chromosomes are paired in the first division." },
      { id: `f-${R}-15`, front: "What is a chiasma?", back: "The point where non-sister chromatids of a homologous pair cross and are joined; where they break and rejoin during crossing over. Plural: chiasmata." },
      { id: `f-${R}-16`, front: "Which chromatids take part in crossing over?", back: "Non-sister chromatids: one from the maternal and one from the paternal chromosome of a homologous pair. Never sister chromatids, never non-homologous chromosomes." },
      { id: `f-${R}-17`, front: "How does crossing over produce genetic variation?", back: "Exchanged sections carry different alleles, so chromatids with new combinations of alleles (recombinant chromatids) are produced and pass into different daughter cells." },
      { id: `f-${R}-18`, front: "Why can all four cells from one meiosis be genetically different?", back: "Independent segregation makes the two cells of the first division different; crossing over makes the sister chromatids different, so the second division also gives two different cells." },
      { id: `f-${R}-19`, front: "What are recombinant chromatids?", back: "Chromatids that carry a combination of alleles not present on either parental chromosome, produced by crossing over (e.g. Ab and aB from AB and ab)." },
      { id: `f-${R}-20`, front: "What is random fertilisation?", back: "Any one of the many genetically different male gametes can fuse with any one of the many genetically different female gametes; which ones fuse is a matter of chance." },
      { id: `f-${R}-21`, front: "How does random fertilisation increase variation?", back: "Each zygote receives a new, unpredictable combination of alleles from two parents, increasing genetic variation within the species." },
      { id: `f-${R}-22`, front: "Zygote combinations from random fertilisation (supporting maths).", back: "(2ⁿ)² = 2ⁿ × 2ⁿ, ignoring crossing over. Humans: about 7.0 × 10¹³." },
      { id: `f-${R}-23`, front: "Why must gametes be haploid?", back: "So that fertilisation restores the diploid number in the zygote, keeping the chromosome number constant from generation to generation." },
      { id: `f-${R}-24`, front: "DNA content per cell through meiosis (x = DNA in a gamete).", back: "2x before replication; 4x after replication; 2x after the first division; x after the second division." },
      { id: `f-${R}-25`, front: "How do you recognise the first division of meiosis in a drawing?", back: "Homologous chromosomes lie side by side in pairs (often with chiasmata) on the equator, or whole two-chromatid chromosomes move to opposite poles; the cell has the diploid number." },
      { id: `f-${R}-26`, front: "How do you recognise the second division of meiosis in a drawing?", back: "The haploid number of chromosomes (no matching pairs), each of two chromatids, lined up singly on the equator, or single chromatids moving apart in a cell with the haploid number (in mitosis the diploid number is present)." },
      { id: `f-${R}-27`, front: "Three differences between meiosis and mitosis (supporting).", back: "Meiosis: two divisions not one; four haploid cells not two diploid ones; homologous chromosomes pair and cross over; daughter cells genetically different, not identical." },
      { id: `f-${R}-28`, front: "When does each source of variation act?", back: "Independent segregation and crossing over: first division of meiosis. Random fertilisation: after meiosis, when gametes fuse." },
      { id: `f-${R}-29`, front: "Does independent segregation change the alleles on a chromosome?", back: "No. It shuffles whole chromosomes. Crossing over changes the combination of alleles on a chromosome." },
      { id: `f-${R}-30`, front: "Do meiosis and fertilisation create new alleles?", back: "No. They produce new combinations of existing alleles. New alleles arise by mutation." },
      { id: `f-${R}-31`, front: "A cell has 2 chromosomes, each of two chromatids, and comes from an organism with 2n = 4. Where is it in meiosis?", back: "After the first division (or in the second division): haploid, chromatids not yet separated, DNA content 2x." },
    ],
    questions: [
      // ---- MCQ ----
      { id: `q-${R}-m1`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "A cell from a rice plant (2n = 24) divides by meiosis. How many chromosomes are in each cell produced?", options: ["6", "12", "24", "48"], answer: 1, explanation: "Meiosis halves the chromosome number: 24 ÷ 2 = 12." },
      { id: `q-${R}-m2`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "How many nuclear divisions take place in meiosis, and how many cells are produced from one parent cell?", options: ["One division; two cells", "Two divisions; two cells", "Two divisions; four cells", "Four divisions; four cells"], answer: 2, explanation: "Two nuclear divisions produce four haploid cells." },
      { id: `q-${R}-m3`, ref: R, stmts: S(1, 5), type: "mcq", marks: 1, stem: "Which statement describes the second division of meiosis?", options: ["Homologous chromosomes separate and the chromosome number halves", "Sister chromatids separate and the chromosome number per cell stays haploid", "Homologous chromosomes pair and cross over", "The DNA replicates"], answer: 1, explanation: "In the second division chromatids separate; the cells were already haploid." },
      { id: `q-${R}-m4`, ref: R, stmts: S(1, 2), type: "mcq", marks: 1, stem: "Which of these best describes a pair of homologous chromosomes?", options: ["Two identical copies of a chromosome joined at a centromere", "One maternal and one paternal chromosome carrying the same genes at the same loci", "Two chromosomes carrying identical alleles", "Any two chromosomes of the same length"], answer: 1, explanation: "Homologous chromosomes carry the same genes at the same loci; their alleles may differ. Option A describes sister chromatids." },
      { id: `q-${R}-m5`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Crossing over produces genetic variation because:", options: ["it creates new alleles", "non-sister chromatids exchange sections carrying different alleles, giving new combinations of alleles", "sister chromatids exchange identical sections", "it doubles the number of chromosomes"], answer: 1, explanation: "Crossing over recombines existing alleles; it creates no new alleles." },
      { id: `q-${R}-m6`, ref: R, stmts: S(3, 5), type: "mcq", marks: 1, stem: "A chiasma is:", options: ["the point where the two sister chromatids of a chromosome are joined", "a point where non-sister chromatids of a homologous pair cross and exchange sections", "the place where spindle fibres attach", "the equator of a dividing cell"], answer: 1, explanation: "Sister chromatids are joined at the centromere; a chiasma joins non-sister chromatids." },
      { id: `q-${R}-m7`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Independent segregation produces genetically different daughter cells because:", options: ["each homologous pair lines up independently, so different combinations of maternal and paternal chromosomes go into the cells", "sister chromatids separate independently", "alleles move independently along a chromosome", "each gamete fuses with any other gamete"], answer: 0, explanation: "The orientation of each pair is random and independent of the others. The last option describes random fertilisation." },
      { id: `q-${R}-m8`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "The fruit fly <em>Drosophila melanogaster</em> has 2n = 8. Ignoring crossing over, how many combinations of chromosomes can its gametes have?", options: ["8", "16", "64", "256"], answer: 1, explanation: "n = 4 pairs: 2⁴ = 16. 256 is (2⁴)², the number for zygotes." },
      { id: `q-${R}-m9`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Independent segregation alone allows an organism to produce 64 combinations of chromosomes in its gametes. How many homologous pairs does it have?", options: ["6", "8", "12", "32"], answer: 0, explanation: "2⁶ = 64, so 6 pairs (2n = 12)." },
      { id: `q-${R}-m10`, ref: R, stmts: S(4), type: "mcq", marks: 1, stem: "Which source of genetic variation is NOT a process within meiosis?", options: ["Independent segregation", "Crossing over", "Random fertilisation", "Separation of homologous chromosomes into different cells"], answer: 2, explanation: "Fertilisation happens after meiosis, when gametes fuse." },
      { id: `q-${R}-m11`, ref: R, stmts: S(2, 4), type: "mcq", marks: 1, stem: "Humans have 23 pairs of chromosomes. Ignoring crossing over, how many chromosome combinations are possible in the zygotes from one couple?", options: ["23² = 529", "2 × 2²³ ≈ 1.7 × 10⁷", "2²³ ≈ 8.4 × 10⁶", "(2²³)² ≈ 7.0 × 10¹³"], answer: 3, explanation: "Each parent can make 2²³ kinds of gamete; any can fuse with any: (2²³)² ≈ 7.0 × 10¹³." },
      { id: `q-${R}-m12`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "A gamete of a mammal contains 3.2 pg of DNA. How much DNA does a cell contain immediately after the first division of meiosis?", options: ["1.6 pg", "3.2 pg", "6.4 pg", "12.8 pg"], answer: 2, explanation: "After the first division each cell has 2x (each chromosome still two chromatids): 2 × 3.2 = 6.4 pg." },
      { id: `q-${R}-m13`, ref: R, stmts: S(1, 5), type: "mcq", marks: 1, stem: "In an organism with 2n = 8, how many chromosomes and chromatids are in each cell immediately after the first division of meiosis?", options: ["8 chromosomes, 16 chromatids", "4 chromosomes, 8 chromatids", "4 chromosomes, 4 chromatids", "8 chromosomes, 8 chromatids"], answer: 1, explanation: "Haploid number (4), each chromosome still two chromatids (8)." },
      { id: `q-${R}-m14`, ref: R, stmts: S(5), type: "mcq", marks: 1, stem: "A drawing of a dividing cell from an animal with 2n = 6 shows three chromosomes, each of two chromatids, lined up singly on the equator. The cell is:", options: ["in the first division of meiosis", "in the second division of meiosis", "in mitosis", "a cell before DNA replication"], answer: 1, explanation: "Haploid number on the equator, not paired: the second division. Mitosis would show six." },
      { id: `q-${R}-m15`, ref: R, stmts: S(5), type: "mcq", marks: 1, stem: "A drawing of a dividing cell from an animal with 2n = 6 shows two groups of three chromosomes moving to opposite poles. Each chromosome is still made of two chromatids, and the three chromosomes in each group are of different lengths. The cell is:", options: ["in the first division of meiosis", "in the second division of meiosis", "in mitosis", "a gamete"], answer: 0, explanation: "Whole chromosomes, still made of two chromatids, are separating, with three (one of each homologous pair, the haploid number) going to each pole: homologous chromosomes are separating in the first division. In the second division, and in mitosis, single chromatids move apart." },
      { id: `q-${R}-m16`, ref: R, stmts: S(5, 3), type: "mcq", marks: 1, stem: "In a photograph of a dividing cell, chromosomes are seen in pairs of the same length, each pair joined by cross-shaped connections. This shows:", options: ["sister chromatids separating in the second division", "homologous chromosomes paired, with chiasmata, in the first division", "a cell in mitosis", "random fertilisation"], answer: 1, explanation: "Pairs of homologous chromosomes with chiasmata appear only in the first division of meiosis." },
      { id: `q-${R}-m17`, ref: R, stmts: S(1, 3), type: "mcq", marks: 1, stem: "If no crossing over occurred, the four cells produced by one meiosis would be:", options: ["all genetically identical", "two pairs of genetically identical cells", "all four genetically different", "genetically identical to the parent cell"], answer: 1, explanation: "Without crossing over, sister chromatids are identical, so each product of the first division gives two identical cells." },
      { id: `q-${R}-m18`, ref: R, stmts: S(1, 4), type: "mcq", marks: 1, stem: "Why is it necessary for gametes to be haploid?", options: ["So that they can divide by mitosis", "So that the zygote formed at fertilisation is diploid, keeping the chromosome number constant between generations", "So that crossing over can take place", "So that they contain more DNA"], answer: 1, explanation: "n + n = 2n." },
      { id: `q-${R}-m19`, ref: R, stmts: S(2, 3), type: "mcq", marks: 1, stem: "Which statement correctly distinguishes the two sources of variation within meiosis?", options: ["Independent segregation exchanges alleles between chromatids; crossing over sorts whole chromosomes", "Independent segregation sorts whole chromosomes; crossing over exchanges sections between non-sister chromatids", "Both happen in the second division", "Both happen at fertilisation"], answer: 1, explanation: "Independent segregation sorts whole chromosomes; crossing over recombines alleles. Both occur in the first division." },
      { id: `q-${R}-m20`, ref: R, stmts: S(5), type: "mcq", marks: 1, stem: "A light micrograph of an anther shows many groups of four small cells lying close together. What do these groups represent?", options: ["Cells that have completed the first division only", "The four haploid products of one meiosis", "Four homologous chromosomes", "Diploid cells about to divide"], answer: 1, explanation: "Groups of four are the products of the second division of one meiosis." },
      { id: `q-${R}-m21`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "<span class=\"badge\">supporting</span> Which feature is found in meiosis but not in mitosis?", options: ["Spindle fibres attach to centromeres", "Chromosomes condense", "Homologous chromosomes pair up", "Sister chromatids separate"], answer: 2, explanation: "Pairing of homologous chromosomes (and crossing over) happens only in meiosis; the other features occur in both." },
      { id: `q-${R}-m22`, ref: R, stmts: S(2, 4), type: "mcq", marks: 1, stem: "Two brothers who are not identical twins have the same parents but differ genetically. Which explanation is complete?", options: ["Mutation only", "Independent segregation and crossing over in each parent's meiosis, and random fertilisation", "Crossing over only", "Random fertilisation only"], answer: 1, explanation: "All three processes contribute; each brother came from a different, genetically different sperm and egg." },
      { id: `q-${R}-m23`, ref: R, stmts: S(3, 1), type: "mcq", marks: 1, stem: "Crossing over occurs:", options: ["between chromosomes of different pairs in the second division", "while homologous chromosomes are paired in the first division", "after fertilisation in the zygote", "before DNA replication"], answer: 1, explanation: "Non-sister chromatids exchange sections while the homologous pair is together in the first division." },
      // ---- gap ----
      { id: `q-${R}-g1`, ref: R, stmts: S(1), type: "gap", marks: 5, stem: "Complete the passage.", text: "Meiosis involves {{1}} nuclear divisions and produces {{2}} daughter cells from one diploid cell. In the first division {{3}} chromosomes separate, so each daughter cell is {{4}}. In the second division sister {{5}} separate.", answers: { 1: ["two", "2"], 2: ["four", "4"], 3: ["homologous"], 4: ["haploid"], 5: ["chromatids"] }, explanation: "Two; four; homologous; haploid; chromatids." },
      { id: `q-${R}-g2`, ref: R, stmts: S(3), type: "gap", marks: 4, stem: "Complete the passage about crossing over.", text: "Crossing over takes place between {{1}} chromatids of {{2}} chromosomes. The point where the chromatids cross is called a {{3}}. Equivalent sections are exchanged, producing new combinations of {{4}}.", answers: { 1: ["non-sister", "nonsister"], 2: ["homologous"], 3: ["chiasma"], 4: ["alleles"] }, explanation: "Non-sister; homologous; chiasma; alleles." },
      { id: `q-${R}-g3`, ref: R, stmts: S(2, 4), type: "gap", marks: 2, stem: "A species of plant has 2n = 12. Ignore crossing over.", text: "Number of chromosome combinations possible in its gametes: {{1}}. Number possible in the zygotes from two parent plants: {{2}}.", answers: { 1: ["64"], 2: ["4096"] }, explanation: "n = 6: 2⁶ = 64; (2⁶)² = 4096." },
      { id: `q-${R}-g4`, ref: R, stmts: S(1), type: "gap", marks: 3, stem: "The DNA content of a sperm cell of a bull is 3.0 pg.", text: "DNA content of a diploid cell before replication: {{1}} pg. After replication, before meiosis begins: {{2}} pg. In each cell after the first division: {{3}} pg.", answers: { 1: ["6", "6.0"], 2: ["12", "12.0"], 3: ["6", "6.0"] }, explanation: "x = 3.0 pg: 2x = 6.0, 4x = 12.0, 2x = 6.0." },
      // ---- matching ----
      { id: `q-${R}-mt1`, ref: R, stmts: S(1, 3, 5), type: "match", marks: 5, stem: "Match each term to its meaning.", pairs: [{ left: "Homologous chromosomes", right: "A maternal and a paternal chromosome with the same genes at the same loci" }, { left: "Sister chromatids", right: "Two identical copies of a chromosome joined at a centromere" }, { left: "Centromere", right: "The region that joins sister chromatids; used to count chromosomes" }, { left: "Chiasma", right: "Point where non-sister chromatids cross and exchange sections" }, { left: "Haploid", right: "Having one chromosome from each homologous pair" }] },
      { id: `q-${R}-mt2`, ref: R, stmts: S(5, 1), type: "match", marks: 4, stem: "An organism has 2n = 4. Match each description of a cell to the point in meiosis it shows.", pairs: [{ left: "4 chromosomes, each one chromatid, not paired", right: "Parent cell before DNA replication" }, { left: "2 homologous pairs side by side on the equator", right: "First division" }, { left: "2 chromosomes, each two chromatids, singly on the equator", right: "Second division" }, { left: "2 chromosomes, each one chromatid", right: "A cell produced at the end of meiosis" }] },
      // ---- sequence ----
      { id: `q-${R}-sq1`, ref: R, stmts: S(1, 2, 3), type: "sequence", marks: 4, stem: "Put these events of meiosis in order.", steps: ["DNA replicates, so each chromosome is two chromatids", "Homologous chromosomes pair up and crossing over occurs", "Homologous pairs line up on the equator, each pair independently", "Homologous chromosomes separate to opposite poles: two haploid cells", "Chromosomes line up singly on the equator", "Sister chromatids separate: four haploid cells"] },
      // ---- labelling ----
      { id: `q-${R}-lab1`, ref: R, stmts: S(3, 5), type: "label", drag: true, marks: 5, stem: "The drawing shows a homologous pair during the first division of meiosis. Label the five numbered features.", svg: A.labelPair(), labels: [{ n: 1, answer: "Centromere" }, { n: 2, answer: "Chiasma" }, { n: 3, answer: "Sister chromatids" }, { n: 4, answer: "Locus of a gene" }, { n: 5, answer: "Homologous pair" }], bank: ["Centromere", "Chiasma", "Sister chromatids", "Locus of a gene", "Homologous pair", "Spindle fibre", "Nuclear envelope", "Equator"] },
      // ---- short answer and application ----
      { id: `q-${R}-s1`, ref: R, stmts: S(2), type: "short", marks: 3, stem: "Explain how independent segregation of homologous chromosomes produces genetically different daughter cells. (3 marks)", scheme: [{ point: "Homologous chromosomes pair / line up on the equator in pairs in the first division", marks: 1 }, { point: "Each pair is arranged independently / at random: either the maternal or the paternal chromosome can go to each pole", marks: 1 }, { point: "So daughter cells receive different combinations of maternal and paternal chromosomes (with different alleles)", marks: 1 }], model: "In the first division of meiosis the homologous chromosomes line up in pairs on the equator. The way each pair is arranged is random and independent of every other pair, so whether the maternal or the paternal chromosome of a pair moves to a given pole is a matter of chance. As a result the daughter cells receive different combinations of maternal and paternal chromosomes, which carry different alleles, so they are genetically different.", commonErrors: "Writing about alleles segregating within a chromosome, or describing crossing over instead." },
      { id: `q-${R}-s2`, ref: R, stmts: S(3), type: "short", marks: 3, stem: "Explain how crossing over leads to genetic variation among the cells produced by meiosis. (3 marks)", scheme: [{ point: "Homologous chromosomes pair; non-sister chromatids cross at chiasmata", marks: 1 }, { point: "Chromatids break and rejoin, exchanging equivalent sections (of DNA / alleles)", marks: 1 }, { point: "Producing new combinations of alleles on chromatids, which go into different cells", marks: 1 }], model: "During the first division homologous chromosomes pair up and their non-sister chromatids become entwined, crossing at points called chiasmata. The chromatids break and rejoin at the chiasmata, exchanging equivalent sections of DNA. Because the sections may carry different alleles, chromatids with new combinations of alleles are formed, and these pass into different daughter cells.", commonErrors: "'Chromosomes swap genes' (they exchange alleles of the same genes, between chromatids); crossing over between sister chromatids." },
      { id: `q-${R}-s3`, ref: R, stmts: S(4), type: "short", marks: 2, stem: "Explain how random fertilisation increases genetic variation within a species. (2 marks)", scheme: [{ point: "Gametes are genetically different (because of meiosis) and any male gamete can fuse with any female gamete / fusion is by chance", marks: 1 }, { point: "So each zygote has a new combination of alleles from two parents", marks: 1 }], model: "Every gamete produced by meiosis is genetically different, and which male gamete fuses with which female gamete is a matter of chance. Each zygote therefore receives a new and unpredictable combination of alleles from its two parents, increasing the variation within the species.", commonErrors: "Saying fertilisation causes crossing over or creates new alleles." },
      { id: `q-${R}-s4`, ref: R, stmts: S(2, 3), type: "short", marks: 3, stem: "A student wrote: 'Independent segregation and crossing over are the same thing, because both mix up maternal and paternal genes.' Explain why the student is wrong. (3 marks)", scheme: [{ point: "Independent segregation sorts whole chromosomes: which homologue of each pair goes into each cell", marks: 1 }, { point: "Crossing over exchanges sections between non-sister chromatids, changing the combination of alleles on a single chromosome", marks: 1 }, { point: "Independent segregation does not change any chromosome; crossing over produces recombinant chromatids (both in the first division but different processes; they add together)", marks: 1 }], model: "Independent segregation sorts whole chromosomes: because each homologous pair lines up independently, a cell receives a random mixture of maternal and paternal chromosomes, but every chromosome is unchanged. Crossing over is different: non-sister chromatids of a homologous pair exchange equivalent sections at chiasmata, so a single chromatid ends up with a new combination of maternal and paternal alleles. The two processes both happen in the first division and their effects add together, but one shuffles whole chromosomes and the other recombines alleles within them.", commonErrors: "Restating one mechanism without contrasting it with the other." },
      { id: `q-${R}-s5`, ref: R, stmts: S(1, 4), type: "short", marks: 2, stem: "Explain why gametes produced by meiosis must be haploid. (2 marks)", scheme: [{ point: "At fertilisation two gametes fuse", marks: 1 }, { point: "Haploid gametes (n + n) restore the diploid number in the zygote, so the chromosome number stays constant between generations (diploid gametes would double it each generation)", marks: 1 }], model: "At fertilisation a male and a female gamete fuse. Because each is haploid, the zygote receives one set from each and is diploid, so the chromosome number of the species stays the same from one generation to the next; diploid gametes would double it every generation.", commonErrors: "'So they have half the DNA' with no link to fertilisation." },
      { id: `q-${R}-s6`, ref: R, stmts: S(5, 1), type: "short", marks: 4, stem: (() => { const m = M.build("three", { cross: [true, false, false], orient: [false, true, true] }); return `The drawing shows a dividing cell from an animal with 2n = 6.<div class="figure"><div class="fig-view">${A.cellFigure(m, "metII", 0, { k: 0.85, tags: false, aria: "a dividing cell with three chromosomes, each of two chromatids, on the equator" })}</div></div>(a) State whether the cell is haploid or diploid, and explain how you can tell from the drawing. (2 marks)\n(b) Identify which division of meiosis the cell is in, and describe what will happen to its chromosomes next. (2 marks)`; })(), scheme: [{ point: "(a) Haploid", marks: 1 }, { point: "(a) Three chromosomes (count centromeres), one of each type / no homologous pairs; half of 2n = 6", marks: 1 }, { point: "(b) Second division: single chromosomes, each of two chromatids, on the equator", marks: 1 }, { point: "(b) Sister chromatids will separate and move to opposite poles, giving two haploid cells", marks: 1 }], model: "(a) The cell is haploid. It contains three chromosomes (three centromeres), all of different lengths, so there is only one chromosome from each homologous pair, half the diploid number of six. (b) It is in the second division of meiosis: the chromosomes lie singly on the equator and each still has two chromatids. Next, the centromeres divide and the sister chromatids are pulled to opposite poles, giving two haploid cells with single-chromatid chromosomes.", commonErrors: "Calling the cell diploid because each chromosome has two chromatids; counting six chromatids as six chromosomes." },
      { id: `q-${R}-s7`, ref: R, stmts: S(2, 4), type: "short", marks: 4, stem: "Application. The domestic dog has 2n = 78. (a) Give the number of chromosomes in a dog sperm. (1 mark) (b) Write an expression for the number of combinations of chromosomes possible in a dog's gametes by independent segregation. (1 mark) (c) Explain why the true number of genetically different gametes a dog can produce is far larger than this. (2 marks)", scheme: [{ point: "(a) 39", marks: 1 }, { point: "(b) 2³⁹ (about 5.5 × 10¹¹)", marks: 1 }, { point: "(c) Crossing over between non-sister chromatids of homologous chromosomes", marks: 1 }, { point: "(c) Produces new combinations of alleles on the chromosomes, at different positions in different cells, multiplying the combinations from independent segregation", marks: 1 }], model: "(a) 39. (b) 2³⁹, about 5.5 × 10¹¹. (c) This counts only independent segregation of whole chromosomes. Crossing over between non-sister chromatids of homologous chromosomes also exchanges sections carrying different alleles, at chiasmata whose positions vary from cell to cell, so each chromosome can carry many different new combinations of alleles and the number of genetically different gametes is vastly larger.", commonErrors: "Using 2⁷⁸; citing random fertilisation, which concerns zygotes, not gametes." },
      { id: `q-${R}-s8`, ref: R, stmts: S(1, 5), type: "short", marks: 2, stem: "A student wrote: 'In the second division of meiosis the chromosome number halves again, so the gametes have a quarter of the parent's chromosomes.' Correct the student's statement. (2 marks)", scheme: [{ point: "The chromosome number halves only in the first division (homologous chromosomes separate); the gametes have half the parent's chromosomes (haploid)", marks: 1 }, { point: "In the second division sister chromatids separate, so the chromosome number per cell stays the same (n); it is the DNA content that halves again", marks: 1 }], model: "The chromosome number halves only once, in the first division, when homologous chromosomes separate, so the gametes are haploid with half the parent's chromosomes, not a quarter. In the second division the sister chromatids of each chromosome separate; each cell keeps the haploid number of chromosomes, and what halves is the DNA content (from 2x to x).", commonErrors: "Confusing DNA content with chromosome number." },
      { id: `q-${R}-d1`, ref: R, stmts: S(1, 5), type: "short", marks: 4, stem: "Data. Scientists measured the DNA content of individual nuclei from the testis of a mammal, and sorted them into three groups.\n<table class=\"tbl\"><thead><tr><th>Group</th><th>DNA per nucleus / arbitrary units</th></tr></thead><tbody><tr><td>P</td><td>3.3</td></tr><tr><td>Q</td><td>6.6</td></tr><tr><td>R</td><td>13.2</td></tr></tbody></table>(a) Which group contains cells formed at the end of meiosis? Explain your answer. (1 mark) (b) Which group contains cells whose DNA has replicated in preparation for meiosis? (1 mark) (c) Group Q contains two kinds of cell at different points in meiosis. Identify them and explain why they have the same DNA content. (2 marks)", scheme: [{ point: "(a) P: lowest DNA content, x; haploid with single-chromatid chromosomes (spermatids / sperm)", marks: 1 }, { point: "(b) R (4x)", marks: 1 }, { point: "(c) Diploid cells before DNA replication, and haploid cells after the first division", marks: 1 }, { point: "(c) Diploid unreplicated: 2n single chromatids; after the first division: n chromosomes of two chromatids each; both = 2x", marks: 1 }], model: "(a) P, because it has the lowest DNA content (x): these are haploid cells whose chromosomes are single chromatids, produced by the second division. (b) R, with 4x, double the content of a diploid cell before replication. (c) Group Q contains diploid cells that have not yet replicated their DNA and haploid cells that have completed the first division. The diploid cells have 2n chromosomes of one chromatid each; the haploid cells have half as many chromosomes but each has two chromatids, so both contain 2x.", commonErrors: "Assuming the same DNA content means the same chromosome number." },
      { id: `q-${R}-s9`, ref: R, stmts: S(3, 1), type: "short", marks: 3, stem: "Application. In a plant, the alleles R and S are on the same chromosome; the other chromosome of the pair carries r and s. Some pollen grains carry chromosomes with R and s. (a) Name the process that produced the chromosome carrying R and s. (1 mark) (b) Explain how this chromosome was produced. (2 marks)", scheme: [{ point: "(a) Crossing over", marks: 1 }, { point: "(b) Homologous chromosomes paired in the first division; non-sister chromatids crossed at a chiasma between the two loci", marks: 1 }, { point: "(b) Broke and rejoined, exchanging equivalent sections so that the S allele was replaced by s on a chromatid that carries R", marks: 1 }], model: "(a) Crossing over. (b) In the first division of meiosis the homologous chromosomes paired. A chromatid of the R S chromosome and a non-sister chromatid of the r s chromosome crossed at a chiasma between the two loci, broke and rejoined, exchanging equivalent sections, so one chromatid ended up carrying R with s. This recombinant chromatid passed into the pollen grain.", commonErrors: "Naming independent segregation, which cannot change the alleles on a chromosome." },
      // ---- extended ----
      { id: `q-${R}-e1`, ref: R, stmts: S(1, 2, 3, 4), type: "extended", marks: 6, stem: "Extended response. Describe how meiosis produces haploid cells from a diploid cell, and explain how meiosis and fertilisation produce genetic variation. (6 marks)", scheme: [{ point: "Two nuclear divisions produce four haploid cells from one diploid cell (DNA replicates before meiosis)", marks: 1 }, { point: "First division: homologous chromosomes separate, halving the chromosome number; second division: sister chromatids separate", marks: 1 }, { point: "Independent segregation: homologous pairs line up independently, giving different combinations of maternal and paternal chromosomes", marks: 1 }, { point: "Crossing over: non-sister chromatids of homologous chromosomes exchange equivalent sections at chiasmata", marks: 1 }, { point: "Producing new combinations of alleles; sister chromatids no longer identical, so all four cells can differ", marks: 1 }, { point: "Random fertilisation: any male gamete can fuse with any female gamete, giving new combinations of alleles in each zygote", marks: 1 }], levels: "Level 3 (5–6): both divisions described correctly with what separates in each, and all three sources of variation explained and kept distinct. Level 2 (3–4): divisions outlined and at least two sources explained. Level 1 (1–2): fragments, or the mechanisms confused.", model: "Before meiosis the DNA replicates, so each chromosome is made of two sister chromatids. Meiosis then involves two nuclear divisions. In the first, homologous chromosomes pair and then separate to opposite poles, so each of the two cells receives one chromosome from every pair and is haploid. In the second, the sister chromatids of each chromosome separate, giving four haploid cells from the original diploid cell. Variation arises in three ways. In the first division each homologous pair lines up on the equator independently of the others, so the cells receive different combinations of maternal and paternal chromosomes: independent segregation. While the homologous chromosomes are paired, non-sister chromatids cross at chiasmata, break and rejoin, exchanging equivalent sections; this crossing over produces chromatids with new combinations of alleles, and because sister chromatids are then no longer identical, all four cells can differ. Finally, at fertilisation any one of these genetically different male gametes can fuse with any female gamete, so each zygote receives a new combination of alleles from two parents, further increasing variation within the species.", alternatives: "Independent segregation is credited for explaining that different cells receive different combinations of maternal and paternal chromosomes. It is not a complete explanation of the differences between the four cells (without crossing over they form two identical pairs), so it does not earn the crossing-over marks.", commonErrors: "Saying the chromosome number halves in both divisions; crossing over between sister chromatids; treating random fertilisation as part of meiosis." },
    ],
  };
})();
